import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Two circles with radii {r1} and {r2} lie inside a larger circle of radius {R}. The two smaller circles are externally tangent to each other and each is internally tangent to the larger circle. There exists a chord of the larger circle that serves as a common external tangent to both smaller circles. Determine the square of the length of this chord.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate integer radii r1 < r2 < R with r1 + r2 < R
# We further prefer cases where R*(R - (r1 + r2)) is not a perfect square to avoid trivial algebra,
# which increases difficulty (irrational square roots appear).
for _ in range(1000):
    R = rng.randint(12, 60)
    # Choose r1 modest compared to R
    r1_low = 2
    r1_high = max(2, R // 4)
    r1 = rng.randint(r1_low, r1_high)
    # Choose r2 ensuring r1 + r2 < R
    r2_low = r1 + 1
    r2_high = max(r2_low, R - r1 - 2)
    if r2_low > r2_high:
        continue
    r2 = rng.randint(r2_low, r2_high)
    if not (r1 < r2 and r2 < R and r1 + r2 < R):
        continue
    a = r1 + r2
    p = r1 * r2
    rad = R * (R - a)
    if rad <= 0:
        # Must be strictly inside
        continue
    # Prefer non-perfect-square radicand for hardness
    s = int(rad ** 0.5)
    if s * s == rad:
        # skip easy instances (can still be solvable, but we prefer harder)
        continue
    # Closed-form for X = R - d using the minus branch (the plus branch often yields invalid d < 0)
    # X = (2 p / a^2) * ((2 R - a) - 2 * sqrt(R(R - a)))
    X = (2.0 * p / (a * a)) * ((2 * R - a) - 2.0 * (rad ** 0.5))
    d = R - X
    # Validate distance domain
    if not (0.0 < d < R):
        continue
    # Chord length squared
    L2 = 4.0 * (R * R - d * d)
    # Avoid very trivial geometric placements: ensure the chord is not extremely close to the center or boundary
    if d < 1.0 or (R - d) < 1.0:
        continue
    # Avoid integer L2 for added difficulty (nontrivial radicals); allow small tolerance
    if abs(round(L2) - L2) < 1e-9:
        continue
    return {'r1': r1, 'r2': r2, 'R': R}
# fallback robust instance (non-perfect-square radicand)
return {'r1': 4, 'r2': 5, 'R': 17}

    def verifier(assign):
# Recompute using the derived closed form and validate constraints to ensure the instance is nontrivial and correct.
try:
    r1 = int(assign.get('r1'))
    r2 = int(assign.get('r2'))
    R = int(assign.get('R'))
except Exception:
    # invalid types
    return (False, None)
# Basic domain checks
if not (r1 > 0 and r2 > 0 and R > 0):
    # radii must be positive
    return (False, None)
if not (r1 < r2 and r2 < R):
    # ordering
    return (False, None)
a = r1 + r2
p = r1 * r2
if not (a < R):
    # must fit inside outer circle
    return (False, None)
rad = R * (R - a)
if rad <= 0:
    # degenerate outer geometry
    return (False, None)
# Enforce nontrivial hardness: avoid r1 == r2 and avoid perfect-square radicand
if r1 == r2:
    # equal radii leads to simpler symmetry
    return (False, None)
s = int(rad ** 0.5)
if s * s == rad:
    # easier closed form (we prefer harder instances)
    return (False, None)
# Compute d using the closed form for X = R - d (minus branch)
import math
X = (2.0 * p / (a * a)) * ((2 * R - a) - 2.0 * math.sqrt(rad))
d = R - X
# Validate chord distance domain
if not (0.0 < d < R):
    # invalid chord (not inside the circle)
    return (False, None)
# Compute chord length squared
L2 = 4.0 * (R * R - d * d)
# Geometric consistency checks:
# For the common external tangent line at distance d from center, the x-offsets of the two centers satisfy
# x_i^2 = (R - d) * (R + d - 2 r_i), and external tangency enforces (|x1| + |x2|)^2 = 4 r1 r2.
A = R - d
B1 = R + d - 2.0 * r1
B2 = R + d - 2.0 * r2
if B1 < 0 or B2 < 0 or A <= 0:
    # centers would not reach the tangent line
    return (False, None)
x1_sq = A * B1
x2_sq = A * B2
if x1_sq < 0 or x2_sq < 0:
    return (False, None)
# Check the external tangency horizontal separation: (|x1| + |x2|)^2 = 4 r1 r2
sep_sq = (math.sqrt(x1_sq) + math.sqrt(x2_sq)) ** 2
if not (abs(sep_sq - 4.0 * p) <= 1e-7 * max(1.0, 4.0 * p)):
    # numerical/geometric mismatch; reject instance
    return (False, None)
# Also ensure the chord is not nearly trivial in length (extremely small or nearly diameter)
chord_len = math.sqrt(L2)
if not (1e-6 < chord_len < 2.0 * R - 1e-6):
    return (False, None)
return (True, L2)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

